    double lB[N][N];
#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=3 dim=1
#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=4 dim=2
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=3 dim=1
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=4 dim=2

    // Load BOTH A and B into local buffers.
    // Correctness requirement: lB boundary elements (row 0, row N-1, col 0,
    // col N-1) are never touched by the interior stencil loops, so they must
    // be pre-loaded from B to avoid writing uninitialized values back to B.
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            lA[i][j] = A[i][j];
            lB[i][j] = B[i][j];
        }
    }

    int t, i, j;

    for (t = 0; t < tsteps; t++) {
        // First stencil sweep: lA -> lB (interior only)
        // lA is read-only, lB is write-only in this sweep: no loop-carried dep.
        for (i = 1; i < n - 1; i++) {
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=lA inter false
#pragma HLS DEPENDENCE variable=lB inter false
                lB[i][j] = 0.2 * (lA[i][j] + lA[i][j-1] + lA[i][1+j]
                                 + lA[1+i][j] + lA[i-1][j]);
            }
        }
        // Second stencil sweep: lB -> lA (interior only)
        // lB is read-only, lA is write-only in this sweep: no loop-carried dep.
        for (i = 1; i < n - 1; i++) {
            for (j = 1; j < n - 1; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=lA inter false
#pragma HLS DEPENDENCE variable=lB inter false
                lA[i][j] = 0.2 * (lB[i][j] + lB[i][j-1] + lB[i][1+j]
                                 + lB[1+i][j] + lB[i-1][j]);
            }
        }
    }

    // Write both local buffers back to global memory
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = lA[i][j];
            B[i][j] = lB[i][j];
